  const b=draft.bands.map(Number);if(!(b[0]>b[1]&&b[1]>=0&&b[0]<=100))throw Error($t('Batas Sangat baik harus lebih tinggi dari batas Baik.','The Very good threshold must be above the Good threshold.'));
  if(role==='staff'&&!(Number.isInteger(+draft.target)&&+draft.target>=1&&+draft.target<=500))throw Error($t('Target harus 1–500 pekerjaan per bulan.','The target must be 1–500 tasks a month.'));
  const L=latestRule(),v=JSON.parse(JSON.stringify(L));v.v=L.v+1;v.from=nextMonth();v.at=ten.now;v.by=state.user;v[role]={...v[role],w};if(role==='staff')v.staff.target=+draft.target;v.bands=b;
