  if(person(id)?.super){const st=TEAM134.staff.map(s=>perf(s,m)),sT=st.reduce((a,x)=>a+x.total,0),sOn=st.reduce((a,x)=>a+x.on,0),wd=workdays(m,id).length,act=new Set(p.items.map(x=>String(x.completed).slice(0,10))).size;
    c=[pc(p.on,p.total),pc(sOn,sT),pc(p.total-p.corrections,p.total),wd?Math.min(100,pc(act,wd)):null];
    why=[[`${p.on} dari ${p.total} keputusan & pekerjaan selesai tepat waktu`,`${p.on} of ${p.total} decisions & tasks done on time`],sT?[`${sOn} dari ${sT} pekerjaan Staf selesai tanpa tertahan`,`${sOn} of ${sT} Staff tasks finished without being held up`]:['Belum ada pekerjaan Staf','No Staff work yet'],[`${p.total-p.corrections} dari ${p.total} tanpa koreksi`,`${p.total-p.corrections} of ${p.total} without corrections`],[`Aktif ${act} dari ${wd} hari kerja (Jejak Kerja)`,`Active ${act} of ${wd} workdays (Work Log)`]];}
  else{const a=attMonth(id,m);
    c=[pc(p.on,p.total),pc(p.total-p.corrections,p.total),Math.min(100,pc(p.total,RU.staff.target)),a?pc(a.ok,a.days):null];
    why=[[`${p.on} dari ${p.total} pekerjaan selesai sebelum batas waktu`,`${p.on} of ${p.total} tasks finished before the deadline`],[`${p.total-p.corrections} dari ${p.total} lolos tanpa dikembalikan`,`${p.total-p.corrections} of ${p.total} passed without being sent back`],[`${p.total} selesai · target ${RU.staff.target} per bulan`,`${p.total} done · target ${RU.staff.target} a month`],a?[`Tepat waktu ${a.ok} dari ${a.days} hari kerja${a.late?` · terlambat ${a.late} kali`:''}`,`On time ${a.ok} of ${a.days} workdays${a.late?` · late ${a.late} times`:''}`]:['Catatan jam bulan ini belum ada — bobotnya dibagi ke ukuran lain','No clock records this month — its weight is shared by the others']];}
