const BANKS=[['bca','BCA','Bank Central Asia'],['mandiri','Mandiri','Bank Mandiri'],['bri','BRI','Bank Rakyat Indonesia'],['bni','BNI','Bank Negara Indonesia'],['bsi','BSI','Bank Syariah Indonesia'],['cimb','CIMB Niaga','CIMB Niaga'],['permata','Permata','Bank Permata'],['danamon','Danamon','Bank Danamon'],['btn','BTN','Bank Tabungan Negara'],['jago','Jago','Bank Jago'],['lain','Bank lain','Bank lain']];
const ACC=()=>{data.salaryAcc152??={jeck:{bank:'bca',no:'8800120917',holder:'Jeck Rotama'},eka:{bank:'mandiri',no:'1370023360',holder:'Eka Poetra'},cantika:{bank:'bsi',no:'7144824821',holder:'Cantika Dewi'}};data.salaryReq152??=[];return data.salaryAcc152;};
const bankOf=k=>BANKS.find(b=>b[0]===k)||BANKS[BANKS.length-1];
const accOf=id=>{const a=ACC()[id];if(!a)return null;const b=bankOf(a.bank);return {...a,key:b[0],short:b[1],full:b[2],last:String(a.no).slice(-4)};};
const reqs=()=>{ACC();return data.salaryReq152;};
const myReq=id=>reqs().find(r=>r.staff===id&&r.status==='pending');
function bankEdit(){const id=me().id,a=accOf(id);
  modal($t('Ubah rekening gaji','Change salary account'),`<form data-form="bank152"><p class="sub">${SA()?$t('Perubahan dikonfirmasi oleh Super Admin lain sebelum dipakai untuk gaji berikutnya.','The other Super Admin confirms the change before it is used for the next pay.'):$t('Perubahan dikonfirmasi Super Admin sebelum dipakai untuk gaji berikutnya.','A Super Admin confirms the change before it is used for the next pay.')}</p><div class="form-grid">${selectField('bank',$t('Bank','Bank'),BANKS.map(b=>[b[0],b[2]]),a?.bank||'bca')}${field('no',$t('Nomor rekening','Account number'),'','text','required inputmode="numeric" autocomplete="off" pattern="[0-9 ]{6,24}"')}${field('holder',$t('Atas nama','Account holder'),a?.holder||nameOf(id),'text','required')}</div>${formEnd($t('Ajukan perubahan','Request the change'))}</form>`);}
document.addEventListener('submit',e=>{const f=e.target;if(!f.matches?.('form[data-form="bank152"]'))return;e.preventDefault();e.stopImmediatePropagation();
  const v=new FormData(f),no=String(v.get('no')||'').replace(/\D/g,''),bank=String(v.get('bank')||''),holder=String(v.get('holder')||'').trim(),id=me().id;
  if(no.length<6||no.length>20){say($t('Nomor rekening harus 6–20 angka.','The account number must be 6–20 digits.'));return;}
  if(holder.length<3){say($t('Tulis nama pemilik rekening.','Enter the account holder name.'));return;}
  if(commit(()=>{reqs().forEach(r=>{if(r.staff===id&&r.status==='pending')r.status='cancelled';});data.salaryReq152.push({id:'BR-'+(reqs().length+1),staff:id,bank,no,holder,at:ten.now,status:'pending'});})){try{closeModal();}catch(err){}say($t('Perubahan rekening diajukan · menunggu konfirmasi','Account change requested · awaiting confirmation'));render();}},true);
function bankDecide(rid,ok){const r=reqs().find(x=>x.id===rid);if(!r||r.status!=='pending'||r.staff===me().id||!SA())return;
  const lbl=`${bankOf(r.bank)[1]} •••• ${String(r.no).slice(-4)}`;
  if(commit(()=>{r.status=ok?'approved':'rejected';r.decided=ten.now;r.by=state.user;if(ok)ACC()[r.staff]={bank:r.bank,no:r.no,holder:r.holder};
    try{addNotification(r.staff,ok?['Rekening gaji diperbarui','Salary account updated']:['Perubahan rekening gaji ditolak','Salary account change declined'],ok?[`Gaji berikutnya dibayar ke ${lbl}.`,`Your next pay goes to ${lbl}.`]:['Hubungi Super Admin untuk keterangan.','Contact a Super Admin for details.'],'compensation');}catch(err){}}))
    say(ok?$t(`Rekening ${nameOf(r.staff)} diperbarui ke ${lbl}`,`${nameOf(r.staff)}'s account updated to ${lbl}`):$t('Perubahan rekening ditolak','Account change declined'));render();}
function bankCancel(){const q=myReq(me().id);if(!q)return;if(commit(()=>{q.status='cancelled';}))say($t('Pengajuan rekening dibatalkan','Account change cancelled'));render();}

/* ---------- potongan tampilan ---------- */
const head=(h,p,right='')=>`<div class="ph"><div><h1>${h}</h1><p>${p}</p></div>${right}</div>`;
const tabs=pg=>!SA()?'':`<div class="segc" role="tablist"><button role="tab" aria-pressed="${V.tab[pg]==='team'}" data-tab="${pg}:team">${$t('Tim','Team')}</button><button role="tab" aria-pressed="${V.tab[pg]==='me'}" data-tab="${pg}:me">${$t('Saya','Me')}</button></div>`;
const howBtn=()=>`<button class="btn sm" data-rules>${IC.book}${$t('Cara menghitung','How it is scored')}</button>`;
function miniBars(id,k){return `<div class="minibars">${comps(id).map((n,i)=>`<span>${$t(...n)}<div class="bar"><i style="width:${k.comps[i]??0}%"></i></div></span>`).join('')}</div>`;}
function kpiHero(id){const ms=histMonths(),m=kpiMonth(),k=kpi152(id,m);if(!k)return `<section class="kpi"><div class="score"><span class="k">${$t('Kinerja','Performance')}</span><b>—</b></div><div><p class="muted">${$t('Belum ada pekerjaan selesai yang tercatat.','No finished work recorded yet.')}</p></div></section>`;
  const [bt,bc]=band(k.score),idx=ms.indexOf(m),prev=idx>0?kpi152(id,ms[idx-1]):null,d=prev?k.score-prev.score:null,tr=ms.slice(Math.max(0,idx-5),idx+1).map(x=>[x,kpi152(id,x)?.score??0]),mx=Math.max(...tr.map(x=>x[1])),mn=Math.min(...tr.map(x=>x[1]))-6;
  return `<section class="kpi"><div class="score"><span class="k">${$t('Kinerja','Performance')} · ${mName(m)}</span><b><span data-cu="${k.score}">${k.score}</span><small>/100</small></b>
   <div class="row"><span class="bandt ${bc==='today'?'warn':''}">${bt}</span>${d!=null?`<span class="delta ${d<0?'dn':d>0?'up':''}">${d?`<span class="tri${d<0?' dn':''}"></span>`:''}<b>${d?Math.abs(d):'='}</b> ${$t('dari ','from ')}${$t(...MON[+ms[idx-1].split('-')[1]-1])}</span>`:''}</div>
   <div class="trend2" aria-label="${$t('Nilai per bulan','Score per month')}">${tr.map(([x,v],i)=>`<span class="${i===tr.length-1?'now':''}"><em>${v}</em><i style="height:${Math.round(6+Math.max(0,v-mn)/((mx-mn)||1)*30)}px"></i><small>${mShort(x)}</small></span>`).join('')}</div></div>
   <div><div class="comp">${comps(id).map((n,i)=>`<div class="cp"><div class="t"><span>${$t(...n)}</span><i>${ruleFor(m)[roleKey(id)].w[i]}%</i></div><b${k.comps[i]!=null?` data-cu="${k.comps[i]}"`:''}>${k.comps[i]??'—'}</b><div class="bar"><i style="width:${k.comps[i]??0}%"></i></div><small>${$t(...k.why[i])}</small></div>`).join('')}</div>
   <div class="howto"><span>${$t('Nilai = tiap ukuran × bobotnya. KPI tidak memengaruhi gaji maupun bonus.','Score = each measure × its weight. KPI does not affect pay or bonuses.')}</span>${howBtn()}</div></div></section>`;}
function rulesBox(){const RU=ruleFor(kpiMonth()),L=latestRule(),col=(h,Ln,rows,w)=>`<div class="rc"><h3>${h}</h3>${Ln.map((n,i)=>`<div class="rr"><b>${w[i]}%</b><div>${$t(...n)}<small>${$t(...rows[i])}</small></div></div>`).join('')}</div>`,b=RU.bands;
  return `<div class="box" role="dialog" aria-modal="true" aria-labelledby="rh"><div class="ch"><h2 id="rh">${$t('Cara menghitung KPI','How KPI is scored')}</h2><button class="icb s" data-close aria-label="${$t('Tutup','Close')}">${IC.close}</button></div>
   <p class="muted" style="font-size:13.5px;line-height:1.55;max-width:640px">${$t(`Dihitung otomatis per bulan dari riwayat kerja dan catatan kehadiran di aplikasi, memakai aturan versi ${RU.v} untuk ${mName(kpiMonth())}. Tidak ada isian manual, jadi semua orang dinilai dengan cara yang sama.`,`Calculated automatically per month from the work history and attendance records in the app, using rules version ${RU.v} for ${mName(kpiMonth())}. No manual input, so everyone is scored the same way.`)}</p>
   <div class="tw">${col($t('Staf','Staff'),COMP_ST,[['Pekerjaan selesai sebelum batas waktu ÷ semua pekerjaan selesai','Tasks finished before the deadline ÷ all finished tasks'],['Pekerjaan yang lolos tanpa koreksi ÷ semua pekerjaan selesai','Tasks passed without correction ÷ all finished tasks'],[`Jumlah selesai ÷ target ${RU.staff.target} per bulan (maksimal 100)`,`Completed ÷ target of ${RU.staff.target} a month (capped at 100)`],['Hari masuk tepat waktu ÷ hari kerja (cuti & libur tidak dihitung). Bila belum ada catatan jam, bobotnya dibagi ke ukuran lain.','On-time days ÷ workdays (leave & holidays excluded). Without clock records, its weight is shared by the others.']],RU.staff.w)}
   ${col('Super Admin',COMP_SA,[['Keputusan & pekerjaan yang selesai tepat waktu ÷ semua','Decisions & tasks done on time ÷ all'],['Pekerjaan Staf yang selesai tanpa tertahan ÷ semua pekerjaan Staf','Staff tasks finished without being held up ÷ all Staff tasks'],['Keputusan & pekerjaan tanpa koreksi ÷ semua','Decisions & tasks without correction ÷ all'],['Hari aktif di Jejak Kerja ÷ hari kerja','Active days in the Work Log ÷ workdays']],RU.sa.w)}</div>
   <div class="bands"><span class="bandt">${$t(`${b[0]}–100 Sangat baik`,`${b[0]}–100 Very good`)}</span><span class="muted">${$t(`${b[1]}–${b[0]-1} Baik`,`${b[1]}–${b[0]-1} Good`)}</span><span class="bandt warn">${$t(`Di bawah ${b[1]} Perlu perhatian`,`Below ${b[1]} Needs attention`)}</span></div>
   ${L.v>RU.v?`<p class="note2">${$t(`Aturan versi ${L.v} sudah diterbitkan dan berlaku mulai ${mName(L.from)}.`,`Rules version ${L.v} is published and applies from ${mName(L.from)}.`)}</p>`:''}
   <div class="howto" style="margin-top:16px"><span>${$t('KPI tidak memengaruhi gaji atau bonus. Aturan baru berlaku mulai bulan berikutnya; nilai lama tidak dihitung ulang.','KPI does not affect pay or bonuses. New rules apply from the next month; past scores are not recalculated.')}</span>${SA()?`<button class="btn sm" data-kpiedit>${$t('Ubah di Aturan KPI','Edit in KPI rules')}</button>`:''}</div></div>`;}
const BAYW='M0,0H64V80C42,80 37.3,62 32,40C26.7,18 22,0 0,0Z';
