function todayActivity(id){const ev=(data.events||[]).filter(e=>e.who===id&&(e.day||day())===day()&&e.category!=='finance'),dn=(data.todayDone||[]).filter(x=>x.staff===id);
  const items=[...dn.map(x=>[String(x.time).padStart(5,'0'),x.title,[$t('Menyelesaikan ','Finished ')+(kinds[x.kind]?$t(...kinds[x.kind]).toLowerCase():'')]]),...ev.map(e=>[String(e.time).replace('.',':').padStart(5,'0'),$t(...(e.text||['',''])),[e.obj||'']])].sort((a,b)=>a[0].localeCompare(b[0]));return items;}
