function todayCard(id){const L=todayActivity(id),r=rec(id,day());const rows=[...(r?.in?[[r.in,$t('Catat masuk','Clocked in'),'']]:[]),...L.map(x=>[x[0],x[1],x[2][0]]),...(r?.out?[[r.out,$t('Catat pulang','Clocked out'),'']]:[])].sort((a,b)=>a[0].localeCompare(b[0]));
  return `<section class="card"><div class="ch"><h3>${$t('Jejak hari ini','Today’s log')}</h3><small class="muted">${dShort(day())}</small></div>${rows.length?`<div class="lines">${rows.map(([tm,t,s])=>`<div class="ln"><span>${esc(t)}${s?`<small>${esc(s)}</small>`:''}</span><b>${tm}</b></div>`).join('')}</div>`:`<p class="muted">${$t('Belum ada aktivitas hari ini.','No activity today yet.')}</p>`}</section>`;}
